package com.maxs.pay.authentication.service;
import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.Date;
@Service public class JwtService { @Value("${security.jwt.secret:01234567890123456789012345678901}") private String secret; public String generate(String subject,String role){ SecretKey key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8)); Instant now=Instant.now(); return Jwts.builder().subject(subject).claim("role",role).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(3600))).signWith(key).compact(); } }